  const effRing = new THREE.Mesh(new THREE.TorusGeometry(0.35, 0.03, 8, 40), new THREE.MeshBasicMaterial({ color: 0xc77dff, transparent: true, opacity: 0.6 })); effRing.position.copy(effSite); G1.add(effRing);
