  const ptrC = V3(0, 0, 0); { let n = 0; for (let i = 0; i < ptr.n; i++) if (ptr.el[i] === 'P') { ptrC.add(V3(ptr.xyz[i * 3], ptr.xyz[i * 3 + 1], ptr.xyz[i * 3 + 2]).multiplyScalar(0.08)); n++; } }
